inputs = ['gihz', 'bu', 'ba', 'hai', 'uhdzk']
outputs = ['gvkayhgz', 'bu', 'ba', 'gavkayh', 'ugxzk']

print("Detailed analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Example {i}: '{inp}' -> '{outp}'")
    if inp != outp:
        # Find differences
        min_len = min(len(inp), len(outp))
        diff_pos = -1
        for j in range(min_len):
            if inp[j] != outp[j]:
                diff_pos = j
                break
        if diff_pos >= 0:
            print(f"  First difference at position {diff_pos}")
            print(f"  Input char: '{inp[diff_pos]}' -> Output char: '{outp[diff_pos]}'")
        else:
            print(f"  Length difference: {len(inp)} -> {len(outp)}")
    print()

